program = '''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Horizontal bars copy the color sequence below their left end across the bar.
    for r in range(h):
        c = 0
        while c < w:
            if g[r][c] != 5 or (c > 0 and g[r][c - 1] == 5):
                c += 1
                continue
            end = c
            while end + 1 < w and g[r][end + 1] == 5:
                end += 1
            seq = []
            rr = r + 1
            while rr < h and g[rr][c] not in (0, 5):
                seq.append(g[rr][c])
                rr += 1
            for k, color in enumerate(seq):
                if r + 1 + k < h:
                    for cc in range(c, end + 1):
                        g[r + 1 + k][cc] = color
            c = end + 1

    # Vertical bars repeat the row pattern adjoining their lower end upward.
    for c in range(w):
        r = 0
        while r < h:
            if g[r][c] != 5 or (r > 0 and g[r - 1][c] == 5):
                r += 1
                continue
            end = r
            while end + 1 < h and g[end + 1][c] == 5:
                end += 1
            first_seed = end
            while first_seed >= r and (c + 1 >= w or g[first_seed][c + 1] in (0, 5)):
                first_seed -= 1
            seed_rows = []
            if first_seed >= r:
                for sr in range(first_seed, end + 1):
                    pattern = []
                    cc = c + 1
                    while cc < w and g[sr][cc] not in (0, 5):
                        pattern.append(g[sr][cc])
                        cc += 1
                    if pattern:
                        seed_rows.append(pattern)
                for k, target_r in enumerate(range(r, end + 1)):
                    pattern = seed_rows[k % len(seed_rows)]
                    for j, color in enumerate(pattern):
                        if c + 1 + j < w:
                            g[target_r][c + 1 + j] = color
            r = end + 1
    return g
'''
